/* Ledgerline: every number is read from window.SITE_DATA (generated by scripts/build_site_data.py). */
(() => {
  "use strict";
  const D = window.SITE_DATA;
  if (!D) return;
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const css = (v) => getComputedStyle(document.documentElement).getPropertyValue(v).trim();

  /* ---------------- formatting ---------------- */
  const nf = (d) => new Intl.NumberFormat("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
  const F = {
    int: (v) => nf(0).format(v),
    dec1: (v) => nf(1).format(v), dec2: (v) => nf(2).format(v), dec4: (v) => nf(4).format(v),
    dec5: (v) => nf(5).format(v), dec6: (v) => nf(6).format(v),
    pct1: (v) => nf(1).format(v * 100) + "%", pct2: (v) => nf(2).format(v * 100) + "%",
    pct2s: (v) => nf(2).format(v * 100) + "%",
    sec: (v) => nf(1).format(v) + " s", min: (v) => nf(0).format(v) + " min",
    raw: (v) => String(v),
  };
  const get = (path) => path.split(".").reduce((o, k) => (o == null ? o : o[k]), { ...D, calc: C });

  /* ---------------- derived values (from data only) ---------------- */
  const G = D.generation, Q = D.quality, M = D.model, R = D.recon, P = D.pipeline;
  const reconTotal = Object.values(R.by_category).reduce((a, b) => a + b, 0);
  const defects = Object.values(G.defects).reduce((a, b) => a + b, 0);
  const reason = (r) => (Q.by_reason.find((x) => x.reason === r) || { rows: 0 }).rows;
  const C = {
    quarantinePct: Q.quarantined / Q.silver_in,
    validPct: Q.valid / Q.silver_in,
    totalMinutes: P.total_seconds / 60,
    recallPct: M.test.recall * 100,
    recallPct2: M.test.recall,
    precisionPct: M.test.precision,
    alertRate: M.test.alert_rate,
    reconPct: R.accuracy * 100,
    defectPct: defects / G.raw_rows,
    gb: G.bytes / 1e9,
    corruptCaught: reason("CORRUPT_RECORD"),
    reconRecordsM: reconTotal / 1e6,
    misclassified: R.misclassified,
    matchedPct: (R.by_category.exact_match + R.by_category.tolerance_match) / reconTotal,
    reconSaving: 1 - R.seconds / (R.manual_minutes_estimate * 60),
    commitCount: D.engineering.commits.length,
    fraudRateValid: G.fraud_transactions / Q.valid,
  };

  /* ---------------- bind static values ---------------- */
  $$("[data-k]").forEach((el) => {
    const v = get(el.dataset.k);
    if (v == null) return;
    el.textContent = (F[el.dataset.f] || F.raw)(v);
  });

  /* ---------------- count-up ---------------- */
  const countUp = (el) => {
    const target = get(el.dataset.count);
    const fmt = F[el.dataset.f] || F.int;
    if (reduced || target == null) { el.textContent = fmt(target ?? 0); return; }
    const dur = 1800, t0 = performance.now();
    const ease = (t) => 1 - Math.pow(1 - t, 4);
    const tick = (now) => {
      const t = Math.min(1, (now - t0) / dur);
      el.textContent = fmt(t < 1 ? target * ease(t) : target);
      if (t < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  };
  $$("[data-count]").forEach((el) => { el.textContent = (F[el.dataset.f] || F.int)(0); });

  /* ---------------- reveal on scroll ---------------- */
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (!e.isIntersecting) return;
      const el = e.target;
      el.classList.add("is-in");
      $$("[data-count]", el).forEach(countUp);
      if (el.matches("[data-count]")) countUp(el);
      io.unobserve(el);
    });
  }, { threshold: 0.01, rootMargin: "0px 0px -10% 0px" });
  const stagger = (parentSel) => $$(parentSel).forEach((p) => $$(":scope > .reveal", p).forEach((el, i) => el.style.setProperty("--d", `${i * 0.08}s`)));
  [".cards3", ".stats", ".lessons", ".bento", ".pane-stack", ".grid-m", ".runs", ".journey"].forEach(stagger);
  $$(".reveal, .timeline").forEach((el) => io.observe(el));

  /* ---------------- nav, progress, active link ---------------- */
  const nav = $("#nav"), bar = $(".progress span");
  let lastY = 0;
  const onScroll = () => {
    const y = scrollY, h = document.documentElement.scrollHeight - innerHeight;
    nav.classList.toggle("is-solid", y > 24);
    nav.classList.toggle("is-hidden", y > 700 && y > lastY + 2);
    if (y < lastY - 2) nav.classList.remove("is-hidden");
    lastY = y;
    bar.style.transform = `scaleX(${h > 0 ? y / h : 0})`;
  };
  addEventListener("scroll", onScroll, { passive: true });
  onScroll();
  const links = $$(".nav__links a");
  const secIO = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (!e.isIntersecting) return;
      links.forEach((a) => a.classList.toggle("is-active", a.getAttribute("href") === `#${e.target.id}`));
    });
  }, { rootMargin: "-45% 0px -50% 0px" });
  links.forEach((a) => { const s = $(a.getAttribute("href")); if (s) secIO.observe(s); });

  /* card spotlight */
  $$(".card").forEach((c) => c.addEventListener("pointermove", (e) => {
    const r = c.getBoundingClientRect();
    c.style.setProperty("--mx", `${e.clientX - r.left}px`);
    c.style.setProperty("--my", `${e.clientY - r.top}px`);
  }));

  /* ---------------- tooltip ---------------- */
  const tip = $("#tooltip");
  const showTip = (html, x, y) => {
    tip.innerHTML = html;
    tip.classList.add("is-on");
    const w = tip.offsetWidth, h = tip.offsetHeight;
    tip.style.left = `${Math.min(innerWidth - w - 12, Math.max(12, x + 14))}px`;
    tip.style.top = `${Math.max(12, y - h - 14)}px`;
  };
  const hideTip = () => tip.classList.remove("is-on");

  /* ---------------- stage metadata ---------------- */
  const STAGE = {
    generate: { label: "Generate", c: "--raw" },
    bronze: { label: "Bronze", c: "--bronze" },
    silver: { label: "Silver", c: "--silver" },
    gold: { label: "Gold", c: "--gold" },
    train: { label: "Train", c: "--gold" },
    score: { label: "Score", c: "--gold" },
    recon: { label: "Reconcile", c: "--mint" },
    export: { label: "Serve", c: "--mint" },
  };
  const segColor = { generate: "--raw", bronze: "--bronze", silver: "--silver", gold: "--gold", train: "#f4dc94", score: "#c9973a", recon: "--mint", export: "#9cf3d1" };
  const colorOf = (v) => (v.startsWith("--") ? `var(${v})` : v);

  /* ---------------- hero flow canvas ---------------- */
  (function flow() {
    const cv = $("#flow");
    if (!cv) return;
    const ctx = cv.getContext("2d");
    const cols = ["--raw", "--bronze", "--silver", "--gold"].map(css);
    const red = css("--vermilion");
    const qRate = C.quarantinePct, fRate = C.fraudRateValid;
    let W = 0, H = 0, dpr = 1, parts = [], rings = [], glow = [0, 0, 0], running = false, last = 0, acc = 0;
    const resize = () => {
      dpr = Math.min(devicePixelRatio || 1, 2);
      const r = cv.getBoundingClientRect();
      W = r.width; H = r.height;
      cv.width = W * dpr; cv.height = H * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    const spawn = (x = -10) => {
      const lane = 0.24 + Math.random() * 0.5;
      parts.push({ x, y: lane * H, base: lane * H, v: (0.09 + Math.random() * 0.07) * W, ph: Math.random() * 6.28, r: 1.3 + Math.random() * 1.3, zone: 0, q: false, f: false, vy: 0, a: 1 });
    };
    const gates = () => [W * 0.25, W * 0.5, W * 0.75];
    const step = (dt) => {
      const g = gates();
      acc += dt * Math.max(9, W / 64);
      while (acc > 1) { spawn(); acc -= 1; }
      for (const p of parts) {
        if (p.q) {
          p.vy += 260 * dt; p.y += p.vy * dt; p.x += p.v * 0.25 * dt; p.a -= dt * 0.7;
          continue;
        }
        p.ph += dt * 2;
        p.x += p.v * dt;
        p.y = p.base + Math.sin(p.ph + p.x * 0.01) * 3;
        const z = p.x > g[2] ? 3 : p.x > g[1] ? 2 : p.x > g[0] ? 1 : 0;
        if (z !== p.zone) {
          glow[z - 1] = 1;
          if (z === 2 && Math.random() < qRate) { p.q = true; p.vy = -20; }
          if (z === 3 && Math.random() < fRate) { p.f = true; rings.push({ p, t: 0 }); }
          p.zone = z;
        }
      }
      parts = parts.filter((p) => p.x < W + 20 && p.a > 0 && p.y < H + 20);
      rings = rings.filter((r) => (r.t += dt) < 1.6 && parts.includes(r.p));
      glow = glow.map((v) => Math.max(0, v - dt * 2.5));
    };
    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      const g = gates();
      g.forEach((x, i) => {
        const grd = ctx.createLinearGradient(x - 40, 0, x + 40, 0);
        grd.addColorStop(0, "rgba(0,0,0,0)");
        grd.addColorStop(0.5, `rgba(236,232,223,${0.035 + glow[i] * 0.05})`);
        grd.addColorStop(1, "rgba(0,0,0,0)");
        ctx.fillStyle = grd; ctx.fillRect(x - 40, 0, 80, H);
        ctx.strokeStyle = "rgba(236,232,223,0.10)"; ctx.setLineDash([2, 6]); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(x, 40); ctx.lineTo(x, H - 40); ctx.stroke();
      });
      ctx.setLineDash([]);
      ctx.fillStyle = "rgba(255,91,61,0.06)";
      ctx.fillRect(W * 0.5, H - 26, W * 0.25, 26);
      for (const p of parts) {
        const col = p.q ? red : cols[p.zone];
        ctx.globalAlpha = Math.max(0, p.a) * (p.zone === 0 ? 0.7 : 1);
        ctx.strokeStyle = col; ctx.lineWidth = p.r * 1.2; ctx.lineCap = "round";
        const tl = p.q ? 0 : Math.min(26, p.v * 0.14);
        const tg = ctx.createLinearGradient(p.x - tl, 0, p.x, 0);
        tg.addColorStop(0, "rgba(0,0,0,0)"); tg.addColorStop(1, col);
        ctx.strokeStyle = p.q ? col : tg; ctx.lineWidth = p.r * 1.1;
        ctx.beginPath(); ctx.moveTo(p.x - tl, p.y - (p.q ? p.vy * 0.04 : 0)); ctx.lineTo(p.x, p.y); ctx.stroke();
        ctx.fillStyle = col; ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, 6.283); ctx.fill();
        ctx.globalAlpha *= 0.18; ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 3.2, 0, 6.283); ctx.fill();
      }
      ctx.globalAlpha = 1;
      for (const r of rings) {
        const k = r.t / 1.6;
        ctx.strokeStyle = red; ctx.globalAlpha = 1 - k; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.arc(r.p.x, r.p.y, 4 + k * 22, 0, 6.283); ctx.stroke();
        ctx.globalAlpha = 1; ctx.fillStyle = red;
        ctx.beginPath(); ctx.arc(r.p.x, r.p.y, 3, 0, 6.283); ctx.fill();
      }
    };
    const loop = (now) => {
      if (!running) return;
      const dt = Math.min(0.05, (now - last) / 1000 || 0.016);
      last = now;
      step(dt); draw();
      requestAnimationFrame(loop);
    };
    const prewarm = () => { parts = []; for (let i = 0; i < 400; i++) step(1 / 30); };
    resize(); prewarm(); draw();
    addEventListener("resize", () => { resize(); prewarm(); draw(); });
    if (reduced) return;
    new IntersectionObserver(([e]) => {
      if (e.isIntersecting && !running) { running = true; last = performance.now(); requestAnimationFrame(loop); }
      else if (!e.isIntersecting) running = false;
    }).observe(cv);
    document.addEventListener("visibilitychange", () => { if (document.hidden) running = false; else if (!running) { running = true; last = performance.now(); requestAnimationFrame(loop); } });
  })();

  /* ---------------- pipeline story ---------------- */
  (function story() {
    const steps = $$(".step");
    const byName = Object.fromEntries(P.steps.map((s) => [s.name, s]));
    const nodes = $("#railNodes");
    steps.forEach((s) => {
      const li = document.createElement("li");
      li.style.setProperty("--c", `var(${STAGE[s.dataset.stage].c})`);
      li.innerHTML = "<span></span>";
      nodes.appendChild(li);
    });
    const lis = $$("li", nodes), fill = $(".rail__fill");
    const set = (i) => {
      const name = steps[i].dataset.stage, s = byName[name], meta = STAGE[name];
      steps.forEach((el, j) => el.classList.toggle("is-active", j === i));
      lis.forEach((li, j) => { li.classList.toggle("is-active", j === i); li.classList.toggle("is-done", j < i); });
      fill.style.transform = `scaleY(${i / (steps.length - 1)})`;
      const panel = $("#stagePanel");
      panel.style.setProperty("--pc", `var(${meta.c})`);
      $("#pStep").textContent = String(i + 1).padStart(2, "0");
      $("#pName").textContent = meta.label;
      $("#pIn").textContent = s.rows_in ? F.int(s.rows_in) : "-";
      $("#pOut").textContent = s.rows_out ? F.int(s.rows_out) : (name === "train" ? "model v" + M.version : "-");
      $("#pSec").textContent = F.sec(s.seconds);
      $("#pBar").style.width = `${(s.seconds / P.total_seconds) * 100}%`;
      $("#pFoot").textContent = `${F.pct1(s.seconds / P.total_seconds)} of the ${F.dec1(C.totalMinutes)}-minute run` +
        (s.rows_quarantined ? ` · ${F.int(s.rows_quarantined)} quarantined` : "");
    };
    set(0);
    const sio = new IntersectionObserver((entries) => {
      entries.forEach((e) => { if (e.isIntersecting) set(steps.indexOf(e.target)); });
    }, { rootMargin: "-48% 0px -48% 0px" });
    steps.forEach((s) => sio.observe(s));
  })();

  /* ---------------- runtime bar ---------------- */
  (function runtime() {
    const bar = $("#runtimeBar"), leg = $("#runtimeLegend");
    P.steps.forEach((s, i) => {
      const seg = document.createElement("div");
      seg.className = "seg";
      seg.tabIndex = 0;
      seg.style.setProperty("--s", s.seconds);
      seg.style.setProperty("--c", colorOf(segColor[s.name]));
      seg.style.setProperty("--d", `${i * 0.07}s`);
      seg.innerHTML = `<span>${Math.round(s.seconds)}s</span>`;
      const html = `<b>${STAGE[s.name].label}</b><br>${F.sec(s.seconds)} · ${F.pct1(s.seconds / P.total_seconds)}<br>rows out ${F.int(s.rows_out)}`;
      seg.addEventListener("pointermove", (e) => showTip(html, e.clientX, e.clientY));
      seg.addEventListener("pointerleave", hideTip);
      seg.addEventListener("focus", () => { const r = seg.getBoundingClientRect(); showTip(html, r.left, r.top); });
      seg.addEventListener("blur", hideTip);
      bar.appendChild(seg);
      const l = document.createElement("div");
      l.style.setProperty("--c", colorOf(segColor[s.name]));
      l.innerHTML = `<b>${STAGE[s.name].label}</b><span>${F.sec(s.seconds)}</span>`;
      leg.appendChild(l);
    });
  })();

  /* ---------------- decisions ---------------- */
  (function decisions() {
    const posRate = F.pct2(M.train_positives / M.train_rows);
    const sec = (n) => F.sec(P.steps.find((s) => s.name === n).seconds);
    const DEC = [
      { k: "Table format", t: "Delta Lake, <em>because history is a feature.</em>", pick: "Delta Lake", alt: ["Plain Parquet", "Apache Iceberg"],
        why: "ACID MERGE for dimension upserts, idempotent appends via txnAppId, CHECK constraints enforced on write, and time travel, so any past run can be replayed from the audit trail. It's also native on Databricks.",
        cost: "It ties the lake to the Delta ecosystem; Iceberg would serve equally well off Databricks. Old versions keep old files, which is exactly why card numbers are tokenized before they land.",
        proof: "The audit table stores the Delta version every job wrote, and <code>fintxn time-travel</code> reads them back." },
      { k: "Compute engine", t: "PySpark, <em>for where it's going, not where it ran.</em>", pick: "PySpark 3.5", alt: ["pandas", "Polars", "DuckDB"],
        why: "The same code runs on a laptop and on Databricks serverless, and scales beyond one machine. Window functions express deduplication and point-in-time features cleanly.",
        cost: "Honestly, 5M rows would fit in Polars or DuckDB on a laptop and run faster. Spark pays for JVM startup and local-mode overhead.",
        proof: `${F.dec1(C.totalMinutes)} minutes end to end locally, including Great Expectations scans. The Databricks bundle reuses the same code with no changes.` },
      { k: "Model", t: "LightGBM, <em>because the data is a table.</em>", pick: "LightGBM", alt: ["Logistic regression", "XGBoost", "Deep nets"],
        why: `Tabular features, a ${posRate} fraud rate in training, and decisions that a risk team must be able to understand. Gradient boosting handles the imbalance with scale_pos_weight, trains fast on a CPU, and reports feature importance by gain.`,
        cost: "There's no learned sequence model over a card's history; that history lives in engineered windows instead. XGBoost would perform about the same; LightGBM won on speed.",
        proof: `The train step took ${sec("train")}, including loading ${F.int(P.steps.find((s) => s.name === "train").rows_in)} rows. PR-AUC on a month the model never saw: ${F.dec4(M.test.pr_auc)}.` },
      { k: "Evaluation", t: "Split by time. <em>Fix the threshold before the test.</em>", pick: "Time split + recall target", alt: ["Random split", "0.5 cutoff"],
        why: "A random shuffle leaks a card's future into its past and inflates scores. Fraud teams plan around how much fraud they must catch, so the threshold is tuned on May to reach 95% recall and applied unchanged to June.",
        cost: "Fewer months to train on, and the first 14 days are dropped as burn-in while the feature windows fill up.",
        proof: `Precision was ${F.pct2(M.valid.precision)} on validation and ${F.pct2(M.test.precision)} on test, so the threshold transferred.` },
      { k: "Privacy", t: "Tokenize at the door, <em>encrypt what remains.</em>", pick: "HMAC at landing", alt: ["Encrypt in silver", "Mask in BI"],
        why: "Delta's history keeps every file version, so a card number written to bronze would stay there forever. HMAC is deterministic, so joins and velocity features still work, but it can't be reversed without the key. Customer PII is encrypted per value with AES-256-GCM.",
        cost: "Key management becomes critical: rotating the HMAC key changes every token.",
        proof: "The Spark SQL implementation was verified bit for bit against Python's hmac, and corrupt lines are scrubbed of anything that looks like a card number." },
      { k: "Data quality", t: "Rules quarantine. <em>Expectations certify.</em>", pick: "Spark rules + GX", alt: ["GX only", "Drop bad rows"],
        why: "Analysts need to know why a row failed. That takes row-level reason codes at scale, which Great Expectations doesn't produce. So Spark rules route rows to quarantine, and a 23-expectation suite certifies what was published. A GX failure means a bug in the cleaning.",
        cost: "Two systems to maintain, and the rules have to stay in sync with the documented contract.",
        proof: `${F.int(G.corrupt_lines)} corrupt lines were injected and ${F.int(C.corruptCaught)} quarantined. ${Q.gx_passed}/${Q.gx_total} expectations passed.` },
      { k: "Object store", t: "SeaweedFS, <em>because MinIO went away.</em>", pick: "SeaweedFS", alt: ["MinIO", "LocalStack"],
        why: "MinIO's community images and binaries stopped being distributed, and its repository was archived. SeaweedFS is Apache-2.0, actively maintained, speaks S3, and supports per-identity bucket policies for access control.",
        cost: "A less familiar name. Its encryption at rest also needed a key-encryption key that the docs don't make obvious.",
        proof: "Switching stores took zero application code changes, only the S3 endpoint in config." },
      { k: "ML ops", t: "MLflow, <em>so every number has a receipt.</em>", pick: "MLflow + registry", alt: ["Pickle files", "Ad-hoc logs"],
        why: "Every training run records its parameters, metrics, plots, and the Delta version of the features table it trained on. Scoring loads whichever model holds the champion alias, so promoting a model is a pointer move, not a redeploy.",
        cost: "A tracking database to run locally (SQLite), and one more dependency. It broke once when SQLAlchemy shipped a release MLflow didn't support.",
        proof: `Model v${M.version} is registered as champion. The v1 metrics are kept for comparison.` },
      { k: "Orchestration", t: "Jobs as code, <em>in two dialects.</em>", pick: "Databricks Asset Bundle", alt: ["Notebooks", "Airflow only"],
        why: "The bundle defines the job graph, compute and parameters in YAML, gets validated in CI, and deploys with one command. An equivalent Airflow DAG covers setups without Databricks, and a parity test fails if the two drift apart.",
        cost: "Two orchestrators to keep in step. The parity test exists because that's easy to get wrong.",
        proof: "Both have the same eight tasks and dependencies, checked on every CI run." },
      { k: "Cost", t: "$0, <em>by design.</em>", pick: "Local-first + free tiers", alt: ["Always-on cloud cluster"],
        why: "Spark local mode on a laptop, Databricks Free Edition, Streamlit Community Cloud and GitHub Actions. The Terraform for AWS is written and validated but never applied, and includes a $5 budget alarm in case it ever is.",
        cost: "Laptop-scale runtimes, and no always-on production environment to point to.",
        proof: `The full ${F.int(G.raw_rows)}-row run used no cloud resources.` },
    ];
    const list = $("#decideList"), panel = $("#decidePanel");
    const render = (i) => {
      const d = DEC[i];
      $$(".decide__tab", list).forEach((b, j) => { b.setAttribute("aria-selected", j === i); b.tabIndex = j === i ? 0 : -1; });
      panel.innerHTML = `<div class="d-body"><p class="d-kicker">Decision ${String(i + 1).padStart(2, "0")} · ${d.k}</p>
        <h3>${d.t}</h3>
        <div class="d-vs"><span class="pick">${d.pick}</span><span class="over">chosen over</span>${d.alt.map((a) => `<span class="alt">${a}</span>`).join("")}</div>
        <div class="d-grid">
          <div style="--k:#1f9e6e"><h4>Why</h4><p>${d.why}</p></div>
          <div style="--k:#d4472c"><h4>What it cost</h4><p>${d.cost}</p></div>
          <div style="--k:#c08a26;grid-column:1/-1"><h4>Evidence</h4><p>${d.proof}</p></div>
        </div></div>`;
    };
    DEC.forEach((d, i) => {
      const b = document.createElement("button");
      b.className = "decide__tab"; b.type = "button"; b.setAttribute("role", "tab");
      b.innerHTML = `<span class="n">${String(i + 1).padStart(2, "0")}</span>${d.k}`;
      b.addEventListener("click", () => render(i));
      b.addEventListener("keydown", (e) => {
        if (!["ArrowDown", "ArrowUp", "ArrowRight", "ArrowLeft"].includes(e.key)) return;
        e.preventDefault();
        const n = (i + (e.key === "ArrowDown" || e.key === "ArrowRight" ? 1 : -1) + DEC.length) % DEC.length;
        render(n); $$(".decide__tab", list)[n].focus();
      });
      list.appendChild(b);
    });
    render(0);
  })();

  /* ---------------- horizontal bars ---------------- */
  const hbars = (el, rows, { color, valueFmt, pctOf } = {}) => {
    const max = Math.max(...rows.map((r) => (pctOf ? 1 : r.v)));
    el.innerHTML = rows.map((r, i) => {
      const w = pctOf ? r.v : r.v / max;
      return `<div class="hbar" data-tip="${r.tip || ""}"><span class="hbar__l" title="${r.l}">${r.l}</span>
        <span class="hbar__t"><i style="--w:${(w * 100).toFixed(2)}%;--c:${r.c || color};--d:${i * 0.05}s"></i></span>
        <span class="hbar__v">${valueFmt(r)}</span></div>`;
    }).join("");
    $$(".hbar", el).forEach((h) => {
      const t = h.dataset.tip; if (!t) return;
      h.addEventListener("pointermove", (e) => showTip(t, e.clientX, e.clientY));
      h.addEventListener("pointerleave", hideTip);
    });
    io.observe(el);
  };
  const pretty = (s) => s.toLowerCase().replace(/_/g, " ");

  hbars($("#reasonChart"), Q.by_reason.map((r) => ({
    l: pretty(r.reason), v: r.rows,
    c: r.reason.startsWith("DUPLICATE") ? "var(--silver)" : r.reason.startsWith("NULL") ? "var(--bronze)" : r.reason === "CORRUPT_RECORD" ? "var(--vermilion)" : "var(--gold)",
    tip: `<b>${r.reason}</b><br>${F.int(r.rows)} rows · ${F.pct1(r.rows / Q.quarantined)} of quarantine`,
  })), { valueFmt: (r) => F.int(r.v) });

  hbars($("#patternChart"), Object.entries(G.fraud_by_pattern).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({
    l: pretty(k), v, c: "var(--vermilion)",
    tip: `<b>${pretty(k)}</b><br>${F.int(v)} fraudulent transactions · ${F.pct1(v / G.fraud_transactions)} of fraud`,
  })), { valueFmt: (r) => F.int(r.v) });

  hbars($("#captureChart"), [...M.capture].sort((a, b) => b.caught / b.fraud - a.caught / a.fraud).map((r) => ({
    l: pretty(r.type), v: r.caught / r.fraud, c: "var(--gold)",
    tip: `<b>${pretty(r.type)}</b><br>${F.int(r.caught)} of ${F.int(r.fraud)} caught in June`,
  })), { pctOf: true, valueFmt: (r) => F.pct1(r.v) });

  hbars($("#featureChart"), M.features.slice(0, 7).map((r, i) => ({
    l: r.name, v: r.gain, c: i === 0 ? "var(--gold)" : "var(--silver)",
    tip: `<b>${r.name}</b><br>${F.pct1(r.gain)} of total gain`,
  })), { pctOf: true, valueFmt: (r) => F.pct1(r.v) });

  /* ---------------- line charts ---------------- */
  const NS = "http://www.w3.org/2000/svg";
  const svgEl = (tag, attrs = {}) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; };
  const lineChart = (host, { series, x, y0, y1, bands, tipFor, h = 260, yTicks = [] }) => {
    const draw = () => {
      host.innerHTML = "";
      const w = host.clientWidth, H = host.clientHeight || h;
      const pad = { l: 44, r: 8, t: 10, b: 22 };
      const n = x.length;
      const sx = (i) => pad.l + (i / (n - 1)) * (w - pad.l - pad.r);
      const sy = (v) => pad.t + (1 - (v - y0) / (y1 - y0)) * (H - pad.t - pad.b);
      const svg = svgEl("svg", { viewBox: `0 0 ${w} ${H}`, role: "img" });
      (bands || []).forEach((b) => {
        const r = svgEl("rect", { x: sx(b.from), y: pad.t, width: Math.max(0, sx(b.to) - sx(b.from)), height: H - pad.t - pad.b, fill: b.fill });
        svg.appendChild(r);
        const t = svgEl("text", { x: sx(b.from) + 8, y: pad.t + 14, fill: css("--muted"), "font-size": 10.5, "font-family": "Geist Mono" });
        t.textContent = b.label; svg.appendChild(t);
      });
      yTicks.forEach((v) => {
        svg.appendChild(svgEl("line", { x1: pad.l, x2: w - pad.r, y1: sy(v), y2: sy(v), stroke: "rgba(236,232,223,.07)" }));
        const t = svgEl("text", { x: pad.l - 8, y: sy(v) + 3.5, fill: css("--faint"), "font-size": 10.5, "text-anchor": "end", "font-family": "Geist Mono" });
        t.textContent = F.pct1(v).replace(".0%", "%"); svg.appendChild(t);
      });
      series.forEach((s, si) => {
        let d = "", started = false;
        s.values.forEach((v, i) => {
          if (v == null) { started = false; return; }
          const cv = Math.max(y0, Math.min(y1, v));
          d += `${started ? "L" : "M"}${sx(i).toFixed(1)},${sy(cv).toFixed(1)}`; started = true;
        });
        if (s.area) {
          const gid = `g${Math.random().toString(36).slice(2, 7)}`;
          const defs = svgEl("defs"), lg = svgEl("linearGradient", { id: gid, x1: 0, x2: 0, y1: 0, y2: 1 });
          lg.append(svgEl("stop", { offset: "0", "stop-color": s.color, "stop-opacity": .28 }), svgEl("stop", { offset: "1", "stop-color": s.color, "stop-opacity": 0 }));
          defs.appendChild(lg); svg.appendChild(defs);
          svg.appendChild(svgEl("path", { d: `${d}L${sx(n - 1)},${H - pad.b}L${sx(0)},${H - pad.b}Z`, fill: `url(#${gid})`, class: "area-fill" }));
        }
        const p = svgEl("path", { d, fill: "none", stroke: s.color, "stroke-width": s.w || 1.6, "stroke-linejoin": "round", "stroke-linecap": "round" });
        svg.appendChild(p);
        if (!reduced) {
          requestAnimationFrame(() => {
            const L = p.getTotalLength();
            p.style.strokeDasharray = L; p.style.strokeDashoffset = L;
            p.getBoundingClientRect();
            p.style.transition = `stroke-dashoffset 2.2s cubic-bezier(.22,1,.36,1) ${si * 0.2}s`;
            const run = () => { p.style.strokeDashoffset = 0; };
            new IntersectionObserver(([e], o) => { if (e.isIntersecting) { run(); o.disconnect(); } }, { threshold: 0.3 }).observe(host);
          });
        }
      });
      // month ticks
      let prev = "";
      x.forEach((d, i) => {
        const m = d.slice(0, 7);
        if (m !== prev) {
          prev = m;
          const t = svgEl("text", { x: sx(i), y: H - 4, fill: css("--faint"), "font-size": 10.5, "font-family": "Geist Mono" });
          t.textContent = new Date(d + "T00:00:00Z").toLocaleString("en-US", { month: "short", timeZone: "UTC" });
          svg.appendChild(t);
        }
      });
      const vline = svgEl("line", { y1: pad.t, y2: H - pad.b, stroke: "rgba(236,232,223,.25)", "stroke-dasharray": "3 3", opacity: 0 });
      svg.appendChild(vline);
      svg.addEventListener("pointermove", (e) => {
        const r = svg.getBoundingClientRect();
        const i = Math.round(((e.clientX - r.left - pad.l) / (w - pad.l - pad.r)) * (n - 1));
        if (i < 0 || i >= n) return;
        vline.setAttribute("x1", sx(i)); vline.setAttribute("x2", sx(i)); vline.setAttribute("opacity", 1);
        showTip(tipFor(i), e.clientX, e.clientY);
      });
      svg.addEventListener("pointerleave", () => { vline.setAttribute("opacity", 0); hideTip(); });
      host.appendChild(svg);
    };
    draw();
    let rt; addEventListener("resize", () => { clearTimeout(rt); rt = setTimeout(draw, 150); });
  };

  // daily pass rate
  (function pass() {
    const vals = Q.daily_pass_rate.map((d) => d.v);
    const lo = Math.min(...vals), hi = Math.max(...vals);
    $("#passRange").textContent = `${F.pct2(lo)} – ${F.pct2(hi)}`;
    const padv = (hi - lo) * 0.6;
    lineChart($("#passSpark"), {
      series: [{ values: vals, color: css("--mint"), area: true, w: 1.4 }],
      x: Q.daily_pass_rate.map((d) => d.d), y0: lo - padv, y1: hi + padv, h: 110,
      tipFor: (i) => `<b>${Q.daily_pass_rate[i].d}</b><br>pass rate ${F.pct2(vals[i])}`,
    });
  })();

  // daily precision / recall
  (function daily() {
    const d = M.daily;
    const idx = (s) => d.findIndex((r) => r.split === s);
    const lastIdx = (s) => d.length - 1 - [...d].reverse().findIndex((r) => r.split === s);
    const bands = [
      { from: idx("train"), to: lastIdx("train"), label: "train · Jan–Apr", fill: "rgba(236,232,223,.015)" },
      { from: idx("valid"), to: lastIdx("valid"), label: "valid · May", fill: "rgba(191,200,212,.05)" },
      { from: idx("test"), to: d.length - 1, label: "test · June", fill: "rgba(234,189,85,.07)" },
    ];
    lineChart($("#dailyChart"), {
      series: [
        { values: d.map((r) => r.recall), color: css("--mint") },
        { values: d.map((r) => r.precision), color: css("--gold") },
      ],
      x: d.map((r) => r.d), y0: 0.8, y1: 1.0, bands, yTicks: [0.8, 0.85, 0.9, 0.95, 1.0],
      tipFor: (i) => `<b>${d[i].d}</b> · ${d[i].split}<br>precision ${d[i].precision == null ? "-" : F.pct1(d[i].precision)}<br>recall ${d[i].recall == null ? "-" : F.pct1(d[i].recall)}<br>fraud rate ${F.dec1(d[i].bps)} bps`,
    });
  })();

  /* ---------------- confusion matrix ---------------- */
  (function cm() {
    const t = M.test;
    $("#cm").innerHTML = `
      <span></span><span class="cm__h">predicted fraud</span><span class="cm__h">predicted legit</span>
      <span class="cm__h cm__h--row">actual fraud</span>
      <div class="cm__c cm__c--tp"><span>true positive</span><b>${F.int(t.tp)}</b></div>
      <div class="cm__c cm__c--fn"><span>missed</span><b>${F.int(t.fn)}</b></div>
      <span class="cm__h cm__h--row">actual legit</span>
      <div class="cm__c cm__c--fp"><span>false alarm</span><b>${F.int(t.fp)}</b></div>
      <div class="cm__c cm__c--tn"><span>true negative</span><b>${F.int(t.tn)}</b></div>`;
  })();

  /* ---------------- recon donut ---------------- */
  (function donut() {
    const order = ["exact_match", "tolerance_match", "missing_in_settlement", "amount_mismatch", "timing", "duplicate", "missing_in_ledger"];
    const col = { exact_match: css("--mint"), tolerance_match: "#2a9d74", missing_in_settlement: css("--vermilion"), amount_mismatch: "#ff8a5c", timing: css("--gold"), duplicate: css("--bronze"), missing_in_ledger: "#c43d2a" };
    const isBreak = (k) => !k.endsWith("match");
    const svg = $("#donut"), r = 80, Cc = 2 * Math.PI * r;
    let off = 0;
    const minFrac = 0.012; // keep tiny slices visible; legend shows exact values
    const fr = order.map((k) => R.by_category[k] / reconTotal);
    const boosted = fr.map((f) => Math.max(f, f > 0 ? minFrac : 0));
    const scale = 1 / boosted.reduce((a, b) => a + b, 0);
    order.forEach((k, i) => {
      const len = boosted[i] * scale * Cc;
      const c = svgEl("circle", { cx: 100, cy: 100, r, stroke: col[k], "stroke-dasharray": `${Math.max(0, len - 2)} ${Cc}`, "stroke-dashoffset": reduced ? -off : Cc });
      c.style.setProperty("--d", `${i * 0.08}s`);
      c.dataset.target = -off;
      const html = `<b>${pretty(k)}</b><br>${F.int(R.by_category[k])} records · ${fr[i] < 0.001 ? F.pct2(fr[i]) : F.pct1(fr[i])}`;
      c.addEventListener("pointermove", (e) => showTip(html, e.clientX, e.clientY));
      c.addEventListener("pointerleave", hideTip);
      svg.appendChild(c);
      off += len;
    });
    new IntersectionObserver(([e], o) => {
      if (!e.isIntersecting) return;
      $$("circle", svg).forEach((c) => c.setAttribute("stroke-dashoffset", c.dataset.target));
      o.disconnect();
    }, { threshold: 0.3 }).observe(svg);
    $("#reconLegend").innerHTML = order.map((k) => `<li><i style="background:${col[k]}"></i><span>${pretty(k)}</span><span class="mono">${F.int(R.by_category[k])}</span><span class="${isBreak(k) ? "brk" : "ok"}">${isBreak(k) ? "break" : "match"}</span></li>`).join("");
  })();

  /* ---------------- tokenization (real HMAC-SHA256 via WebCrypto) ---------------- */
  (function tokenize() {
    const pan = $("#pan"), tok = $("#token"), btn = $("#retoken");
    const enc = new TextEncoder();
    let keyP = crypto.subtle ? crypto.subtle.importKey("raw", enc.encode("ledgerline-demo-key"), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]) : null;
    const luhn = (body) => {
      let s = 0;
      body.split("").reverse().forEach((ch, i) => { let d = +ch; if (i % 2 === 0) { d *= 2; if (d > 9) d -= 9; } s += d; });
      return String((10 - (s % 10)) % 10);
    };
    const randPan = () => { let b = "4"; for (let i = 0; i < 14; i++) b += Math.floor(Math.random() * 10); return b + luhn(b); };
    const group = (p) => p.replace(/(\d{4})(?=\d)/g, "$1 ");
    const scramble = (el, final) => {
      if (reduced) { el.textContent = final; return; }
      const hex = "0123456789abcdef"; let f = 0; const total = 22;
      const t = setInterval(() => {
        f++;
        const k = Math.floor((f / total) * final.length);
        el.textContent = final.slice(0, k) + Array.from({ length: final.length - k }, () => hex[Math.floor(Math.random() * 16)]).join("");
        if (f >= total) { clearInterval(t); el.textContent = final; }
      }, 32);
    };
    const run = async (p) => {
      pan.textContent = group(p);
      $("#last4").textContent = p.slice(-4);
      if (!keyP) { tok.textContent = "WebCrypto unavailable (needs HTTPS)"; return; }
      const sig = await crypto.subtle.sign("HMAC", await keyP, enc.encode(p));
      const h = [...new Uint8Array(sig)].map((b) => b.toString(16).padStart(2, "0")).join("");
      scramble(tok, h);
    };
    let done = false;
    new IntersectionObserver(([e], o) => { if (e.isIntersecting && !done) { done = true; run("4111111111111111"); o.disconnect(); } }, { threshold: 0.4 }).observe(tok);
    btn.addEventListener("click", () => { $(".tokenize__row .lbl").textContent = "PAN (synthetic, Luhn-valid)"; run(randPan()); });
  })();

  /* ---------------- audit table ---------------- */
  (function audit() {
    const note = { generate: "raw files only", train: "logs to MLflow registry" };
    const rows = D.audit.map((a) => {
      const t = Object.entries(a.tables);
      const chips = t.length ? t.map(([k, v]) => `<span>${k}<b>v${v}</b></span>`).join("") : `<span>${note[a.job] || "-"}</span>`;
      return `<div class="audit__row"><span class="mono">${a.job}</span><span class="audit__ok">${a.status.toLowerCase()}</span><span class="mono">${F.sec(a.duration_s)}</span><span class="mono">${a.rows_out ? F.int(a.rows_out) : "-"}</span><span class="vchips">${chips}</span></div>`;
    });
    $("#auditTable").innerHTML = `<div class="audit__row audit__row--head"><span>job</span><span>status</span><span>duration</span><span>rows out</span><span>Delta versions written</span></div>` + rows.join("");
    const silver = D.audit.find((a) => a.job === "silver");
    if (silver) $("#ttRun").textContent = `${silver.run_id}…`;
  })();

  /* ---------------- copy buttons ---------------- */
  $$(".copy").forEach((b) => b.addEventListener("click", async () => {
    try { await navigator.clipboard.writeText(b.dataset.copy); b.textContent = "Copied"; b.classList.add("is-done"); }
    catch { b.textContent = "Select & copy"; }
    setTimeout(() => { b.textContent = "Copy"; b.classList.remove("is-done"); }, 1800);
  }));
})();
